import{_ as l,o as e,c as i,O as t}from"./chunks/framework.ccd0435f.js";const r="/pms-doc/assets/cg-qllb1.549c8ac6.png",o="/pms-doc/assets/cg-qllb2.aa13cc9a.png",h="/pms-doc/assets/cg-qllb3.ea2c8eee.png",s="/pms-doc/assets/cg-qllb4.3ae913b4.png",n="/pms-doc/assets/cg-qllb5.70d14d8d.png",f=JSON.parse('{"title":"缺料列表","description":"","frontmatter":{},"headers":[],"relativePath":"采购管理/缺料列表.md","filePath":"采购管理/缺料列表.md"}'),c={name:"采购管理/缺料列表.md"};function u(d,a,p,_,b,q){return e(),i("div",null,a[0]||(a[0]=[t('<h1 id="缺料列表" tabindex="-1">缺料列表 <a class="header-anchor" href="#缺料列表" aria-label="Permalink to &quot;缺料列表&quot;">​</a></h1><blockquote><p>&quot;缺料列表“ 位于采购管理板块 ，所采购的任何成品/物料都会流转到缺料列表中 ​</p></blockquote><h4 id="_1-批量询价" tabindex="-1">1.批量询价 <a class="header-anchor" href="#_1-批量询价" aria-label="Permalink to &quot;1.批量询价&quot;">​</a></h4><ul><li><p>勾选所需要询价的产品/物料（可一键勾选）勾选完成点击批量询价按钮在弹窗中添加供方，填写询价数量，需求货期</p></li><li><p>可添加多个供方一起询价，点击提交数据会流转到采购管理-询价列表，显示草稿状态</p><p>-可点击添加备注</p></li><li><p>相同型号规格的会合并处理，询价数量为合计值，需求货期会取最小值</p></li></ul><h4 id="_2-批量分发" tabindex="-1">2.批量分发 <a class="header-anchor" href="#_2-批量分发" aria-label="Permalink to &quot;2.批量分发&quot;">​</a></h4><ul><li>勾选所需要分发的产品/物料（可一键勾选）勾选完成点击批量分发按钮在弹窗中选择分配采购人员，备注信息</li><li>分发明细：可查看单号，产品交期，产品名称，型号</li></ul><h4 id="_3-型号规格" tabindex="-1">3.型号规格 <a class="header-anchor" href="#_3-型号规格" aria-label="Permalink to &quot;3.型号规格&quot;">​</a></h4><ul><li>分为产品和物料，用图标区分</li></ul><h4 id="_4-收货型号" tabindex="-1">4.收货型号 <a class="header-anchor" href="#_4-收货型号" aria-label="Permalink to &quot;4.收货型号&quot;">​</a></h4><ul><li>当生产安排时，有工艺路线且工序是外部工序，走采购时会到缺料列表中，显示收货型号</li><li>收货型号：填写收货的型号，当收到货物时将对应填写的型号进入库存</li></ul><h4 id="_5-自定义表头" tabindex="-1">5.自定义表头 <a class="header-anchor" href="#_5-自定义表头" aria-label="Permalink to &quot;5.自定义表头&quot;">​</a></h4><ul><li>点击自定义表头图标可进行自定义表头设置</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_6-外发明细" tabindex="-1">6.外发明细 <a class="header-anchor" href="#_6-外发明细" aria-label="Permalink to &quot;6.外发明细&quot;">​</a></h4><ul><li>外发时产生的明细，点击可查看详细明细</li><li>外发明细分为：外发零件/外发部件，根据产品的工艺路线中工序所配的零件/部件展示详情</li><li>只有生产安排时，有工艺路线且工序是外部工序，走采购的才显示外发明细</li></ul><h4 id="_7-相同需求" tabindex="-1">7.相同需求 <a class="header-anchor" href="#_7-相同需求" aria-label="Permalink to &quot;7.相同需求&quot;">​</a></h4><ul><li>如果页面中有相同的产品/型号/规格时，会在相同需求中显示出来</li></ul><p><img src="'+o+'" alt="如图所示"></p><h4 id="_8-询价" tabindex="-1">8.询价 <a class="header-anchor" href="#_8-询价" aria-label="Permalink to &quot;8.询价&quot;">​</a></h4><ul><li><p>可对这个产品/物料进行询价，点击询价按钮在弹窗中填写供方信息，询价数量，需求货期</p></li><li><p>可添加多个供方一起询价，点击提交数据会流转到采购管理-询价列表，显示草稿状态</p><p>-可点击添加备注</p></li></ul><h4 id="_9-分发" tabindex="-1">9. 分发 <a class="header-anchor" href="#_9-分发" aria-label="Permalink to &quot;9. 分发&quot;">​</a></h4><ul><li>点击分发按钮选择采购员，填写备注信息</li></ul><h4 id="_10-申请发料" tabindex="-1">10.申请发料 <a class="header-anchor" href="#_10-申请发料" aria-label="Permalink to &quot;10.申请发料&quot;">​</a></h4><ul><li>可选择外发零件/外发部件</li><li>支持添加零件/部件</li></ul><h4 id="_11-完结" tabindex="-1">11.完结 <a class="header-anchor" href="#_11-完结" aria-label="Permalink to &quot;11.完结&quot;">​</a></h4><ul><li>点击完结可结束这个任务</li></ul><p><img src="'+h+'" alt="如图所示"></p><h1 id="外发任务" tabindex="-1">外发任务 <a class="header-anchor" href="#外发任务" aria-label="Permalink to &quot;外发任务&quot;">​</a></h1><blockquote><p>申请发料后数据会流转到外发任务中，在外放任务中可发料，补发</p></blockquote><h4 id="_1-发料" tabindex="-1">1.发料 <a class="header-anchor" href="#_1-发料" aria-label="Permalink to &quot;1.发料&quot;">​</a></h4><ul><li>点击发料按钮输入供方信息，物料单号，收货人，收货地址，选择收货型号，填写外发量，备注信息</li></ul><h4 id="_2-补料" tabindex="-1">2.补料 <a class="header-anchor" href="#_2-补料" aria-label="Permalink to &quot;2.补料&quot;">​</a></h4><ul><li>发料完成以后还可以进行补料</li><li>输入供方信息，物料单号，收货人，收货地址，可选择收货型号，填写补发量，备注信息</li></ul><p><img src="'+s+'" alt="如图所示"></p><h1 id="发货单" tabindex="-1">发货单 <a class="header-anchor" href="#发货单" aria-label="Permalink to &quot;发货单&quot;">​</a></h1><blockquote><p>在外发任务中发料完成后，生成发货单，可在发货单页面进行装箱</p></blockquote><h4 id="_1-外发人员" tabindex="-1">1.外发人员 <a class="header-anchor" href="#_1-外发人员" aria-label="Permalink to &quot;1.外发人员&quot;">​</a></h4><ul><li>鼠标悬浮在外发人员名称上显示这个人员的基本信息（名称，部门，电话）</li></ul><h4 id="_2-装箱" tabindex="-1">2.装箱 <a class="header-anchor" href="#_2-装箱" aria-label="Permalink to &quot;2.装箱&quot;">​</a></h4><ul><li>点击设置图标可编辑包装箱信息</li><li>点击黄色包装箱图片可查看/编辑装箱量</li></ul><h4 id="_3-新增包装箱" tabindex="-1">3.新增包装箱 <a class="header-anchor" href="#_3-新增包装箱" aria-label="Permalink to &quot;3.新增包装箱&quot;">​</a></h4><ul><li>点击新增图标可添加包装箱数量</li></ul><p><img src="'+n+'" alt="如图所示"></p>',43)]))}const k=l(c,[["render",u]]);export{f as __pageData,k as default};
